# -*- coding: utf-8 -*-
p='sokolov-tree.html'
s=open(p,encoding='utf-8').read()
def rep(a,b):
    global s
    assert s.count(a)==1, (s.count(a), a[:60])
    s=s.replace(a,b)
rep('viewBox="0 0 1400 1180"','viewBox="0 -170 1400 1350"')
rep('for (let g = 1; g <= 8; g++)','for (let g = 1; g <= 10; g++)')
rep('"V", "VI", "VII", "VIII"][g]','"V", "VI", "VII", "VIII", "IX", "X"][g]')
rep('{ id: "ivand",     g: 7, x: 90,   n: "Иван Дмитриевич", s: "Соколов · 1830–1871"','{ id: "ivand",     g: 7, x: 90,   n: "Иван Дмитриевич", s: "Соколов · 1829/30–1870/71"')
rep('{ id: "dmitriy",   g: 8, x: 90,   n: "Дмитрий Иванович", s: "Соколов · помещик", st: "one", c: "ivand" },',
 '{ id: "dmitriy",   g: 8, x: 90,   n: "Дмитрий Иванович", s: "Соколов · ок. 1802–1888", st: "one", c: "ivand" },\n    { id: "apukhtina", g: 8, x: 260,  n: "Анна Федоровна", s: "Апухтина", st: "one", c: "ivand" },\n    { id: "ivann",     g: 9, x: 90,   n: "Иван Николаевич", s: "Соколов · поручик, предводитель", st: "one", c: "dmitriy" },\n    { id: "glazunova", g: 9, x: 260,  n: "Александра Андреевна", s: "Глазунова", st: "one", c: "dmitriy" },\n    { id: "nikolayo",  g: 10, x: 90,  n: "Николай Осипович", s: "Соколов · XVIII в.", st: "one", c: "ivann" },')
rep('    dmitriy: "Карачевский у. Орловской губ. (приход с. Старого)",',
 '    dmitriy: "Карачевский у. Орловской губ. (приход с. Старого)",\n    apukhtina: "Орловская губ.",\n    ivann: "Карачевский у.; д. Вышняя Костеевка Кромской округи; приход с. Рождественского (Дурневка); Орёл (попечительный о тюрьмах комитет)",\n    glazunova: "Орловская губ.",\n    nikolayo: "Орловская губ.(?)",')
old_d='<details class="person s-one" id="dmitriy"><summary><span class="pname">Соколов Дмитрий Иванович</span><span class="pyrs">помещик Карачевского уезда</span><span class="badge"><i class="dot"></i>упомянут в метрике</span></summary><div class="pbody"><p>«Приходский помещик», отец Ивана Дмитриевича. Самый ранний известный Соколов по мужской линии.</p><p class="src">Метрика о браке, 1853 (по выписке Вики)</p></div></details>'
new_d=('<details class="person s-one" id="dmitriy"><summary><span class="pname">Соколов Дмитрий Иванович</span><span class="pyrs">ок. 1802 – ок. 1888</span><span class="badge"><i class="dot"></i>метрика + РРФ</span></summary><div class="pbody"><p>«Приходский помещик», отец Ивана Дмитриевича. В Российском родословном фонде (РРФ) записан так: родился около 1802 года, умер около 1888-го. Жена — Анна Федоровна Апухтина. Дети: Иван (1829–1870), Пелагея (умерла 10.11.1886), Митрофан (1841–1897). Митрофан Дмитриевич значится в списке дворян Карачевского уезда, имевших право голоса на выборах.</p><p class="src">Метрика о браке, 1853 (по выписке Вики); <a href="https://www.rgfond.ru/person/340740">РРФ — Дмитрий Иванович</a>; <a href="https://baza.vgd.ru/1/30975/all.htm">ВГД — список дворян Карачевского у.</a></p></div></details>\n'
 '      <details class="person s-one" id="apukhtina"><summary><span class="pname">Соколова (Апухтина) Анна Федоровна</span><span class="pyrs">1800-е</span><span class="badge"><i class="dot"></i>одна родословная база</span></summary><div class="pbody"><p>Жена Дмитрия Ивановича, мать Ивана Дмитриевича. Известна только по РРФ.</p><p class="src"><a href="https://www.rgfond.ru/person/340740">РРФ</a></p></div></details>\n'
 '      <details class="person s-one" id="ivann"><summary><span class="pname">Соколов Иван Николаевич</span><span class="pyrs">2-я пол. XVIII в. – ?</span><span class="badge"><i class="dot"></i>одна родословная база со ссылками на РГИА</span></summary><div class="pbody"><p>Отец Дмитрия Ивановича. В 1789 году окончил Артиллерийский и инженерный шляхетский кадетский корпус, выпущен штык-юнкером во 2-й канонирский полк, позже поручик артиллерии. В 1818–1827 годах — <b>карачевский уездный предводитель дворянства</b>. С 1823 года член, затем директор Орловского попечительного о тюрьмах комитета. Жена — Александра Андреевна Глазунова. Восемь детей, среди них Иван Иванович (1795) и Дмитрий (ок. 1802). Род внесён в 3-ю часть дворянской родословной книги Орловской губернии в 1811 и 1834 годах «по заслугам отца». Владения — в Карачевском уезде и в деревне Вышней Костеевке Кромской округи, приход села Рождественского (Дурневка).</p><p class="flag">Источник — одна генеалогическая база (биограф С. В. Черепанов). Она ссылается на дело РГИА ф.1343 оп.29 д.5125 (1854) и адрес-календарь 1818 года. Сами документы мы ещё не видели.</p><p class="src"><a href="https://www.rgfond.ru/person/19818">РРФ — Иван Николаевич Соколов</a></p></div></details>\n'
 '      <details class="person s-one" id="glazunova"><summary><span class="pname">Соколова (Глазунова) Александра Андреевна</span><span class="pyrs">2-я пол. XVIII в.</span><span class="badge"><i class="dot"></i>одна родословная база</span></summary><div class="pbody"><p>Жена Ивана Николаевича Соколова, мать Дмитрия Ивановича.</p><p class="src"><a href="https://www.rgfond.ru/person/19818">РРФ</a></p></div></details>\n'
 '      <details class="person s-one" id="nikolayo"><summary><span class="pname">Соколов Николай Осипович</span><span class="pyrs">2-я четверть XVIII в.</span><span class="badge"><i class="dot"></i>одна родословная база</span></summary><div class="pbody"><p>Отец Ивана Николаевича и Василия Николаевича. Самый ранний известный предок по линии Соколовых: это восемь поколений от тебя. Через него род получил дворянство: внук внесён в книгу «по заслугам отца». Его отец — Осип (Иосиф) Соколов, живший около 1700 года.</p><p class="src"><a href="https://www.rgfond.ru/person/19818">РРФ</a></p></div></details>')
rep(old_d,new_d)
rep('поэтому где именно стоял полк, пока неизвестно.</p>',
 'поэтому где именно стоял полк, пока неизвестно.</p><p><b>Где стоял полк (найдено 30.10.2026).</b> По справочнику Генштаба «Боевой состав Советской Армии» 4-й полк ВНОС в 1943 году был не в Москве. С февраля по июнь он входил в Воронежско-Борисоглебский дивизионный район ПВО Воронежского фронта, с июля по октябрь — в Воронежский корпусной район (Западный фронт ПВО), в ноябре — в Курский, в декабре — в Киевский корпусной район ПВО. Командир — майор Н. М. Кривицкий. Значит, баба Ася служила на постах ВНОС от Воронежа до Курска и Киева, двигаясь вслед за фронтом.</p><p><b>Кто мог быть её отцом.</b> Среди участников войны есть один человек с таким именем — <b>Розин Маркел Александрович</b>: родился в 1883 или 1888 году в Скопине Рязанской губернии, член партии с 1917 года, в 1918–1946 годах служил интендантом, подполковник, начальник склада НКО № 568, ордена «Знак Почёта» (1943) и Красного Знамени (1944). Это только гипотеза: имя редкое, но ни один документ не связывает его с Александрой.</p><p class="src"><a href="http://www.soldat.ru/files/f/boevoj_sostav_sa_1943.pdf">Боевой состав Советской Армии, 1943</a> · <a href="https://proza.ru/2015/03/29/1257">Воронежская военная энциклопедия, т. 2</a> · <a href="https://pamyat-naroda.ru/heroes/person-hero45635083/">Розин М. А. — УПК</a> · <a href="https://pamyat-naroda.ru/heroes/podvig-chelovek_predstavlenie12105600/">наградной лист</a></p>')
rep('Чтобы продолжить, нужны отчество и год рождения Николая Выдрина и древо тёти Светы.</p>',
 'Чтобы продолжить, нужны отчество и год рождения Николая Выдрина и древо тёти Светы.</p><p><b>Где жили Выдрины рядом с Казахстаном</b> (связь с нашей семьёй не установлена):</p><ul><li>Оренбургское казачье войско, Уйская станица. Здесь есть посёлок Выдринский (сейчас с. Выдрино Челябинской области, у границы с Кустанайской областью). По краеведческим данным, его основала в середине XVIII века семья Выдриных «из северных губерний». Ревизии 1816–1834 годов сохранились. В 1928–1939 годах 19 Выдриных оттуда приговорили к расстрелу, и родня потом скрывала, что они «из Выдриных».</li><li>Сибирское казачье войско, станица Песчанская под Павлодаром, рядом с Качирами, где родился Н. П. Выдрин (1923). Там жил Выдрин Василий Сергеевич (1902–1975).</li><li>Усть-Каменогорск, около 1904–1910 годов: Выдрины, родня казачьего атамана С. В. Иванова.</li><li>Вятка, деревня Выдрины: роспись рода начинается с Фёдора, 1687 год, но к Казахстану отношения не имеет.</li></ul><p class="src"><a href="https://forum.vgd.ru/4098/119356/20.htm">ВГД — Выдрино (Уйская ст.)</a> · <a href="https://archive74.ru/news/k-100-letiyu-grazhdanskoy-voyny-pravda-zelenoy-voyny">ОГАЧО — Выдрины</a> · <a href="https://ru.wikipedia.org/wiki/Выдрин,_Степан_Семёнович">Википедия — С. С. Выдрин</a> · <a href="https://pavlodarica.fandom.com/wiki/Песчаное">Песчаное (Павлодар)</a> · <a href="https://rodnaya-vyatka.ru/blog/1088/122312">Выдрины, Вятка</a></p>')
rep('    <section>\n      <h3>Семейные материалы</h3>',
 '    <section>\n      <h3>Найдено 30.10.2026</h3>\n      <ul>\n        <li><a href="https://www.rgfond.ru/person/19818">РРФ — Соколов Иван Николаевич</a>, <a href="https://www.rgfond.ru/person/340740">Дмитрий Иванович</a>, <a href="https://www.rgfond.ru/person/340742">Иван Дмитриевич</a>, <a href="https://www.rgfond.ru/person/340744">Сергей Иванович</a>, <a href="https://www.rgfond.ru/person/340747">Сергей Сергеевич</a> (биограф С. В. Черепанов; ссылки на РГИА ф.1343 оп.29 д.5125)</li>\n        <li><a href="https://baza.vgd.ru/1/30975/all.htm">ВГД — дворяне-избиратели Карачевского у.</a> (Митрофан Дм. Соколов); <a href="https://goldarms.narod.ru/orel.htm">дворянские роды Орловской губ.</a>; <a href="https://forum.vgd.ru/post/2172/74786/p2247665.htm">кромской предводитель В. А. Шеншин (1885)</a></li>\n        <li><a href="http://www.soldat.ru/files/f/boevoj_sostav_sa_1943.pdf">Боевой состав Советской Армии, 1943</a>; <a href="https://proza.ru/2015/03/29/1257">Воронежская военная энциклопедия</a> — 4 полк ВНОС</li>\n        <li>Память народа: <a href="https://pamyat-naroda.ru/heroes/person-hero45635083/">Розин Маркел Александрович (УПК)</a>, <a href="https://pamyat-naroda.ru/heroes/person-hero80374336/">награды</a>; <a href="https://pamyat-naroda.ru/heroes/person-hero81323973/">Выдрин Николай Петрович 1923</a>; поиск «Выдрин Николай» — 204 карточки</li>\n        <li><a href="https://www.moypolk.ru/soldiers/vydrin-nikolay-mihaylovich">Бессмертный полк — Выдрин Н. М. 1924 (исключён)</a>; <a href="https://familio.org/surnames/2a4b6f6b-5d58-454e-ac63-ec3cb03b232b">Familio — фамилия Выдрин</a>; <a href="https://nashipredki.com/surname/vydriny-iz-derevni-zhilino-kulemesovskaya-37217">Наши предки — Выдрины, Холмогорский у.</a></li>\n        <li>Выдрины-казаки: <a href="https://forum.vgd.ru/4098/119356/20.htm">ВГД</a>, <a href="https://archive74.ru/news/k-100-letiyu-grazhdanskoy-voyny-pravda-zelenoy-voyny">ОГАЧО</a>, <a href="https://pomnirod.ru/materialy-k-statyam/kazaki/imennoj-spisok-kazakov-vtorogo-voennogo-otdela-orenburgskogo-kazachego-vojska.html">список казаков 2-го отдела ОКВ</a>, <a href="https://archive74.ru/sites/default/files/spravochnik_familiy_kazakov_orenburgskogo_kazachego_voyska_po_naselennym_punktam_1816-1834_gg._1.pdf">справочник фамилий казаков ОКВ 1816–1834</a>, <a href="https://pavlodarica.fandom.com/wiki/Песчаное">Песчаное</a>, <a href="https://olketanu-shko.kz/ru/ust-kamenogorsk-i-ustkamenogorchy-v-k-hih-nach-hhvv/">Усть-Каменогорск</a>, <a href="https://rodnaya-vyatka.ru/blog/1088/122312">Вятка</a></li>\n        <li>Фраеры: <a href="https://www.odessa3.org/collections/war/ewz/link/ewzmsc40.txt">EWZ ewzmsc40</a>, <a href="https://www.odessa3.org/collections/war/ewz/link/ewzmsc28.txt">ewzmsc28</a>, <a href="https://www.odessa3.org/collections/war/ewz/link/ewzmsc19.txt">ewzmsc19</a>, <a href="https://www.odessa3.org/collections/war/ewz/link/ewzmsc87.txt">ewzmsc87</a>, <a href="https://www.odessa3.org/collections/war/link/executel.txt">расстрелянные немцы 1937–38</a>, <a href="https://www.1archive-online.com/keler/list-f-1.html">список Келера</a>, <a href="https://wolgadeutsche.net/koehler/sondersiedlung/sondersiedlung_f.pdf">спецпоселенцы Одесской обл. (Ф)</a></li>\n        <li>Яндекс Архив, сверка годов Бедаревых: <a href="https://ya.ru/archive/catalog/b6b92d4b-4047-4a45-8078-275c6a317d78/37">д.73 ск.37 («1875»)</a>, <a href="https://ya.ru/archive/catalog/e42a102d-489c-4576-895f-ff655205ec3f/265">д.108 ск.265</a>, <a href="https://ya.ru/archive/catalog/ccd3ca76-193d-421d-92e7-e93ea0690ce8/34">оп.6 д.1 ск.34 (титул 1897)</a>, <a href="https://ya.ru/archive/catalog/85ebaabe-6fd7-41ce-ad20-7843617e0702/76">д.657 ск.76</a></li>\n        <li>Закрыто/недоступно (не обходили): blackseagr.org и forum.wolgadeutsche.net (Cloudflare), ru.openlist.wiki (вход), memo.ru (не открывается), rgfond.ru/rod/340740 (429)</li>\n      </ul>\n    </section>\n\n    <section>\n      <h3>Семейные материалы</h3>')
open(p,'w',encoding='utf-8').write(s)
